# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""In-place foreach scalar-list subtraction (aten::_foreach_sub_.ScalarList).

Candidate entry point: ``run(self, scalars)``.

For each index i:  self[i] = self[i] - scalars[i]   (in place, ascending order)

The reference (ATen / FlagGems) performs the subtraction in the tensor's opmath
type (fp32 for fp16/bf16) and stores back into the original storage.  No new
storage is created; non-contiguous views keep their layout, so addresses are
computed from the tensor's own shape/stride metadata.

The reference schema is ``-> ()``: the call returns no value.

Launch strategy: consecutive compatible tensors (same dtype, contiguous,
non-aliasing, at most 4) are fused into a single kernel launch.  The grid is the
sum of the members' block counts and each program picks its tensor from scalar
block boundaries, so per-program state is still exactly one tensor's block and
the memory access pattern is identical to the per-tensor kernel.  This keeps the
number of host launches at one for the common uniform list.

Arithmetic: 16-bit dtypes subtract in the storage dtype (one vector pass) instead
of promoting to fp32 and narrowing (three passes plus a 32 KB staging tile).
"""

import torch
import triton
import triton.language as tl

_MAX_RANK = 8
_MAX_FUSE = 4
_BLOCK_CAP = 8192
_BLOCK_CAP_HALF = 16384
# A 16384-element 16-bit tile already needs the full 192 KB UB on this target, so
# the tile cap cannot be raised further (32768 fails to compile: ub overflow).
_F16 = torch.float16
_BF16 = torch.bfloat16
_NEXT_POW2 = triton.next_power_of_2

_TL_DTYPE = {
    torch.float16: tl.float16,
    torch.bfloat16: tl.bfloat16,
    torch.float32: tl.float32,
    torch.float64: tl.float64,
    torch.int8: tl.int8,
    torch.uint8: tl.uint8,
    torch.int16: tl.int16,
    torch.int32: tl.int32,
    torch.int64: tl.int64,
}


@triton.jit
def _sub_block(
    X,
    PID,
    N,
    S,
    EVEN: tl.constexpr,
    I64: tl.constexpr,
    HALF: tl.constexpr,
    OUT_DTYPE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    if I64:
        offs = PID.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    else:
        offs = PID * BLOCK + tl.arange(0, BLOCK)
    if EVEN:
        x = tl.load(X + offs)
    else:
        if I64:
            mask = offs < N.to(tl.int64)
        else:
            mask = offs < N
        x = tl.load(X + offs, mask=mask, other=0)
    if HALF:
        y = x - S.to(OUT_DTYPE)
    else:
        y = x - S
    if EVEN:
        tl.store(X + offs, y.to(OUT_DTYPE))
    else:
        tl.store(X + offs, y.to(OUT_DTYPE), mask=mask)


@triton.jit(do_not_specialize=["N"])
def _sub_flat(
    X,
    N,
    S,
    EVEN: tl.constexpr,
    I64: tl.constexpr,
    HALF: tl.constexpr,
    OUT_DTYPE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    _sub_block(X, tl.program_id(0), N, S, EVEN, I64, HALF, OUT_DTYPE, BLOCK)


@triton.jit(do_not_specialize=["N0", "N1", "N2", "N3", "C0", "C1", "C2"])
def _sub_multi(
    X0,
    N0,
    S0,
    X1,
    N1,
    S1,
    X2,
    N2,
    S2,
    X3,
    N3,
    S3,
    C0,
    C1,
    C2,
    EVEN: tl.constexpr,
    I64: tl.constexpr,
    HALF: tl.constexpr,
    OUT_DTYPE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    if pid < C0:
        _sub_block(X0, pid, N0, S0, EVEN, I64, HALF, OUT_DTYPE, BLOCK)
    elif pid < C1:
        _sub_block(X1, pid - C0, N1, S1, EVEN, I64, HALF, OUT_DTYPE, BLOCK)
    elif pid < C2:
        _sub_block(X2, pid - C1, N2, S2, EVEN, I64, HALF, OUT_DTYPE, BLOCK)
    else:
        _sub_block(X3, pid - C2, N3, S3, EVEN, I64, HALF, OUT_DTYPE, BLOCK)


@triton.jit
def _sub_tile(
    X, PID, S, HALF: tl.constexpr, OUT_DTYPE: tl.constexpr, BLOCK: tl.constexpr
):
    """One full, in-bounds tile: no bounds mask, 32-bit offsets, straight-line body."""
    offs = PID * BLOCK + tl.arange(0, BLOCK)
    x = tl.load(X + offs)
    if HALF:
        y = x - S.to(OUT_DTYPE)
    else:
        y = x - S
    tl.store(X + offs, y.to(OUT_DTYPE))


@triton.jit
def _sub_quad(
    X0,
    X1,
    X2,
    X3,
    S0,
    S1,
    S2,
    S3,
    HALF: tl.constexpr,
    OUT_DTYPE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """Four equal-length contiguous tensors in one launch with the fewest args.

    The tensor comes from program_id(1) and the block from program_id(0), so no
    block-count scalar is needed.  Callers guarantee each tensor length is an
    exact multiple of BLOCK and below 2**31, so the tile body needs neither a
    bounds mask nor 64-bit offsets.
    """
    pid = tl.program_id(0)
    t = tl.program_id(1)
    if t == 0:
        _sub_tile(X0, pid, S0, HALF, OUT_DTYPE, BLOCK)
    elif t == 1:
        _sub_tile(X1, pid, S1, HALF, OUT_DTYPE, BLOCK)
    elif t == 2:
        _sub_tile(X2, pid, S2, HALF, OUT_DTYPE, BLOCK)
    else:
        _sub_tile(X3, pid, S3, HALF, OUT_DTYPE, BLOCK)


@triton.jit
def _sub_strided(
    X,
    N,
    S,
    RANK: tl.constexpr,
    HALF: tl.constexpr,
    OUT_DTYPE: tl.constexpr,
    SH0: tl.constexpr,
    SH1: tl.constexpr,
    SH2: tl.constexpr,
    SH3: tl.constexpr,
    SH4: tl.constexpr,
    SH5: tl.constexpr,
    SH6: tl.constexpr,
    SH7: tl.constexpr,
    ST0: tl.constexpr,
    ST1: tl.constexpr,
    ST2: tl.constexpr,
    ST3: tl.constexpr,
    ST4: tl.constexpr,
    ST5: tl.constexpr,
    ST6: tl.constexpr,
    ST7: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid.to(tl.int64) * BLOCK + tl.arange(0, BLOCK).to(tl.int64)
    mask = offs < N.to(tl.int64)
    rem = offs
    off = tl.zeros([BLOCK], dtype=tl.int64)
    if RANK > 7:
        off += (rem % SH7) * ST7
        rem = rem // SH7
    if RANK > 6:
        off += (rem % SH6) * ST6
        rem = rem // SH6
    if RANK > 5:
        off += (rem % SH5) * ST5
        rem = rem // SH5
    if RANK > 4:
        off += (rem % SH4) * ST4
        rem = rem // SH4
    if RANK > 3:
        off += (rem % SH3) * ST3
        rem = rem // SH3
    if RANK > 2:
        off += (rem % SH2) * ST2
        rem = rem // SH2
    if RANK > 1:
        off += (rem % SH1) * ST1
        rem = rem // SH1
    if RANK > 0:
        off += (rem % SH0) * ST0
        rem = rem // SH0
    x = tl.load(X + off, mask=mask, other=0)
    if HALF:
        y = x - S.to(OUT_DTYPE)
    else:
        y = x - S
    tl.store(X + off, y.to(OUT_DTYPE), mask=mask)


def _collapse(shape, strides):
    """Drop size-1 dims and merge adjacent dims that are laid out contiguously."""
    dims = [(int(s), int(st)) for s, st in zip(shape, strides) if int(s) != 1]
    merged = []
    for s, st in dims:
        if merged and merged[-1][1] == st * s:
            merged[-1] = (merged[-1][0] * s, st)
        else:
            merged.append((s, st))
    if not merged:
        merged = [(1, 1)]
    return merged


def _as_number(s):
    if isinstance(s, torch.Tensor):
        return s.item()
    return s


def _pick_block(numel, cap):
    b = _NEXT_POW2(numel)
    if b > cap:
        b = cap
    elif b < 64:
        b = 64
    return b


def _launch_group(ts, grp, per, single, block):
    """ts: all tensors; grp: indices of a contiguous, same-dtype, aliasing-free run."""
    k = len(grp)
    t0 = ts[grp[0]]
    dtype = t0.dtype
    is_half = dtype is torch.float16 or dtype is torch.bfloat16
    is_float = dtype.is_floating_point
    out_dtype = _TL_DTYPE[dtype]

    p0 = ts[grp[0]]
    if per is None:
        s0 = float(single) if is_float else int(single)
        scalars = [s0] * k
    else:
        scalars = [float(per[g]) if is_float else int(per[g]) for g in grp]

    total = 0
    cums = []
    even = True
    big = False
    for g in grp:
        m = ts[g].numel()
        total += -(-m // block)
        cums.append(total)
        if m % block:
            even = False
        if m >= (1 << 31):
            big = True

    cp = (cums + [total, total])[:3]
    pad = _MAX_FUSE - k
    ptrs = [ts[g] for g in grp]
    ns = []
    for g in grp:
        ns.append(ts[g].numel())
    if pad:
        ptrs += [p0] * pad
        ns += [1] * pad
        ss = scalars + [scalars[-1]] * pad
    else:
        ss = scalars

    args = (
        ptrs[0],
        ns[0],
        ss[0],
        ptrs[1],
        ns[1],
        ss[1],
        ptrs[2],
        ns[2],
        ss[2],
        ptrs[3],
        ns[3],
        ss[3],
        cp[0],
        cp[1],
        cp[2],
        even,
        big,
        is_half,
        out_dtype,
        block,
    )
    _sub_multi[(total,)](*args)


def _launch_single(t, s, cap=None):
    numel = t.numel()
    is_half = t.dtype is torch.float16 or t.dtype is torch.bfloat16
    sarg = float(s) if t.dtype.is_floating_point else int(s)
    out_dtype = _TL_DTYPE[t.dtype]
    if cap is None:
        cap = _BLOCK_CAP_HALF if is_half else _BLOCK_CAP
    if t.is_contiguous():
        block = _pick_block(numel, cap)
        even = (numel % block) == 0
        i64 = numel >= (1 << 31)
        args = (t, numel, sarg, even, i64, is_half, out_dtype, block)
        _sub_flat[(-(-numel // block),)](*args)
    else:
        dims = _collapse(t.shape, t.stride())
        if len(dims) > _MAX_RANK:
            raise RuntimeError("unsupported tensor rank for in-place foreach sub")
        shape = [1] * _MAX_RANK
        stride = [0] * _MAX_RANK
        for i, (sd, st) in enumerate(dims):
            shape[i] = sd
            stride[i] = st
        block = _pick_block(numel, cap)
        _sub_strided[(-(-numel // block),)](
            t,
            numel,
            sarg,
            len(dims),
            is_half,
            out_dtype,
            shape[0],
            shape[1],
            shape[2],
            shape[3],
            shape[4],
            shape[5],
            shape[6],
            shape[7],
            stride[0],
            stride[1],
            stride[2],
            stride[3],
            stride[4],
            stride[5],
            stride[6],
            stride[7],
            block,
        )


def foreach_sub_scalar_list_(self, scalars):
    if type(self) is list:
        tensors = self
    elif isinstance(self, torch.Tensor):
        tensors = [self]
    else:
        tensors = list(self)
    n = len(tensors)
    if n == 0:
        return None

    single = None
    per = None
    if isinstance(scalars, (int, float)):
        single = scalars
    elif isinstance(scalars, torch.Tensor) and scalars.numel() == 1:
        single = _as_number(scalars)
    else:
        per = [_as_number(s) for s in scalars]
        if len(per) != n:
            raise RuntimeError(
                "Tensor list length %d does not match scalar list length %d"
                % (n, len(per))
            )

    if n == 4:
        # Straight-line path for the common uniform list: four contiguous
        # same-dtype tensors of equal length, no shared storage.
        t0 = tensors[0]
        t1 = tensors[1]
        t2 = tensors[2]
        t3 = tensors[3]
        dt = t0.dtype
        numel = t0.numel()
        if (
            numel
            and t1.dtype is dt
            and t2.dtype is dt
            and t3.dtype is dt
            and t1.numel() == numel
            and t2.numel() == numel
            and t3.numel() == numel
            and t0.is_contiguous()
            and t1.is_contiguous()
            and t2.is_contiguous()
            and t3.is_contiguous()
        ):
            p0 = t0.data_ptr()
            p1 = t1.data_ptr()
            p2 = t2.data_ptr()
            p3 = t3.data_ptr()
            if (
                p0 != p1
                and p0 != p2
                and p0 != p3
                and p1 != p2
                and p1 != p3
                and p2 != p3
            ):
                is_float = dt.is_floating_point
                if dt is _F16 or dt is _BF16:
                    is_half = True
                    block = _pick_block(numel, _BLOCK_CAP_HALF)
                else:
                    is_half = False
                    block = _pick_block(numel, _BLOCK_CAP)
                conv = float if is_float else int
                nb = -(-numel // block)
                if numel == nb * block and numel < (1 << 31):
                    if per is None:
                        s0v = conv(single)
                        s1v = s2v = s3v = s0v
                    else:
                        s0v = conv(per[0])
                        s1v = conv(per[1])
                        s2v = conv(per[2])
                        s3v = conv(per[3])
                    _sub_quad.foreach_sub_scalar_list_(
                        t0,
                        t1,
                        t2,
                        t3,
                        s0v,
                        s1v,
                        s2v,
                        s3v,
                        is_half,
                        _TL_DTYPE[dt],
                        block,
                        grid=(nb, 4),
                        warmup=False,
                    )
                    return None

    i = 0
    while i < n:
        t0 = tensors[i]
        if t0.numel() == 0:
            i += 1
            continue
        s0 = single if per is None else per[i]
        if t0.is_contiguous() and i + 1 < n:
            dt = t0.dtype
            t1 = tensors[i + 1]
            if t1.dtype is dt and t1.is_contiguous() and t1.numel() != 0:
                seen = [t0.data_ptr()]
                p1 = t1.data_ptr()
                if p1 not in seen:
                    grp = [i, i + 1]
                    seen.append(p1)
                    j = i + 2
                    while j < n and len(grp) < _MAX_FUSE:
                        tj = tensors[j]
                        if (
                            tj.dtype is not dt
                            or not tj.is_contiguous()
                            or tj.numel() == 0
                        ):
                            break
                        key = tj.data_ptr()
                        if key in seen:
                            break
                        seen.append(key)
                        grp.append(j)
                        j += 1
                    m = tensors[grp[0]].numel()
                    for g in grp:
                        n_g = tensors[g].numel()
                        if n_g < m:
                            m = n_g
                    if dt is torch.float16 or dt is torch.bfloat16:
                        block = _pick_block(m, _BLOCK_CAP_HALF)
                    else:
                        block = _pick_block(m, _BLOCK_CAP)
                    _launch_group(tensors, grp, per, single, block)
                    i += len(grp)
                    continue
        _launch_single(t0, s0)
        i += 1

    return None
